TpMegaMenu={desktopNav:null,mobileNav:null,duration:null,init:()=>{const M=TpMegaMenu;M.desktopNav=document.querySelector('nav.wp-block-navigation');M.mobileNav=document.querySelector('nav.tp-megamenu-mobile-menu');M.type=M.desktopNav.getAttribute('data-megamenu-animate');M.duration=M.type=='animate'?0.3:M.type=='zoom'?0.25:0;M.isBlur=M.desktopNav.getAttribute('data-megamenu-blur')==='1';if(M.isBlur){M.blurOverlay=document.createElement('DIV');M.blurOverlay.id='megamenublur';document.querySelector('body').prepend(M.blurOverlay)}
document.querySelectorAll('.tp-megamenu-block-nav').forEach(nav=>{const mega=nav.querySelector('.tp-megamenu-block');mega.inAnimate=!1;mega.isShown=!1;mega.isMobile=!1;mega.nav=nav;mega.classList.add(M.type=='zoom'?'zoomanim':M.type=='animate'?'maskanim':'');M.resizeDesktop(mega);window.addEventListener('resize',e=>{M.resizeDesktop(mega)});if(M.desktopNav.getAttribute('data-megamenu-openby')=='click'){nav.addEventListener('click',e=>{let a=e.target.tagName=='A'?e.target:e.target.closest('a');if(!mega.contains(a)){e.preventDefault();if(mega.isShown){M.hideMega(mega)}else{M.showMega(mega)}}},!0)}else{nav.querySelector('.wp-block-navigation-item__content').addEventListener('mouseover',e=>{if(mega.isShown)return;M.showMega(mega)});nav.addEventListener('mouseout',function(e){let el=e.toElement||e.relatedTarget;if(this.contains(el)||el==this)return;M.hideMega(mega)})}});if(M.mobileNav){const mega=M.mobileNav.querySelector('.tp-megamenu-mobile-block');mega.inAnimate=!1;mega.isShown=!1;mega.isMobile=!0;mega.nav=M.mobileNav.querySelector('.tp-megamenu-mobile-nav');M.resizeMobile(mega);window.addEventListener('resize',()=>{M.resizeMobile(mega)});window.addEventListener('scroll',()=>{M.resizeMobile(mega)});mega.nav.addEventListener('click',e=>{e.preventDefault();if(mega.isShown){M.hideMega(mega)}else{M.showMega(mega)}})}
document.addEventListener('click',e=>{const target=e.target;document.querySelectorAll('.tp-megamenu-block').forEach(mega=>{if(mega.isShown&&!(target.closest('.tp-megamenu-block-nav')&&target.closest('.tp-megamenu-block-nav').contains(mega))){M.hideMega(mega)}});if(M.mobileNav){const navMega=M.mobileNav.querySelector('.tp-megamenu-mobile-block');if(navMega&&navMega.isShown&&!M.mobileNav.contains(target)){M.hideMega(navMega)}}})},clearContainment:mega=>{for(let el=mega.parentElement;el&&el!==document.body;el=el.parentElement){const cs=getComputedStyle(el);if(cs.contentVisibility&&cs.contentVisibility!='visible'){el.style.setProperty('content-visibility','visible','important')}
if(cs.contain&&cs.contain!='none'){el.style.setProperty('contain','none','important')}}},resizeDesktop:mega=>{const wideRect=mega.closest('.alignwide').getBoundingClientRect(),liRect=mega.closest('li').getBoundingClientRect(),inner=mega.querySelector('.tp-megamenu-block-inner');inner.style.width=wideRect.width+'px';mega.style.width=wideRect.width+(wideRect.left*2)+'px';mega.style.left=(-liRect.left)+'px';mega.style.top=liRect.height+'px';if(mega.isShown){mega.style.display='block'}else{mega.style.display='none'}},resizeMobile:mega=>{const topBar=document.querySelector('.topbar');const sticky=document.querySelector('.menubar.sticky');const header=document.querySelector('header');let topOffset=0;if(sticky){const r=sticky.getBoundingClientRect();topOffset=r.top+r.height}else if(header){const hr=header.getBoundingClientRect();topOffset=hr.top+hr.height;if(topBar){const tr=topBar.getBoundingClientRect();if(tr.bottom>0){topOffset-=tr.height}}}
mega.style.top=topOffset+'px';if(mega.isShown){mega.height=(window.innerHeight-topOffset)+'px'}else{mega.style.display='none'}},showMega:(mega)=>{if(mega.inAnimate)return;mega.inAnimate=!0;mega.nav.classList.add('tp-megamenuopen');mega.isShown=!0;const M=TpMegaMenu;z=5000,h=mega.isMobile?(window.innerHeight-parseInt(mega.style.top))+'px':'auto';document.querySelectorAll('.tp-megamenu-block').forEach(m=>{if(m.style.zIndex>=z)z=m.style.zIndex+1});mega.style.zIndex=z;if(!mega.isMobile){M.resizeDesktop(mega);if(M.isBlur)M.blurOverlay.classList.add('active')}
if(M.type=='zoom'){_tpt.gsap.set(mega,{height:h,transformOrigin:"50% 0%",transformPerspective:800});mega.anim=_tpt.gsap.fromTo(mega,{scale:1,opacity:0,filter:"blur(7px)",rotationX:-10,y:60},{scale:1,opacity:1,filter:"blur(0px)",rotationX:0,y:0,display:"block",duration:M.duration,ease:"sine.Out",onComplete:()=>{mega.inAnimate=!1;if(mega.isMobile){document.documentElement.classList.add('html-no-scroll');window.addEventListener('scroll',TpMegaMenu.stickyScroll)}}})}else{mega.anim=_tpt.gsap.to(mega,{height:h,display:"block",duration:M.duration,ease:"sine.out",onComplete:()=>{mega.inAnimate=!1;if(mega.isMobile){document.documentElement.classList.add('html-no-scroll');window.addEventListener('scroll',TpMegaMenu.stickyScroll)}}})}},hideMega:(mega)=>{const M=TpMegaMenu;mega.inAnimate=!0;mega.nav.classList.remove('tp-megamenuopen');mega.style.zIndex=5000;if(M.isBlur){let c=0;document.querySelectorAll('.tp-megamenu-block').forEach(m=>{if(m.isShown&&!M.isMobile)c++});if(c==1)M.blurOverlay.classList.remove('active')}
if(mega.isMobile){document.documentElement.classList.remove('html-no-scroll');window.removeEventListener('scroll',M.stickyScroll)}
if(mega.anim)mega.anim.kill();if(M.type=='zoom'){mega.anim=_tpt.gsap.to(mega,{scale:1,opacity:0,filter:"blur(7px)",rotationX:-5,y:30,display:"none",duration:M.duration,ease:"sine.Out",onComplete:()=>{mega.inAnimate=!1;mega.isShown=!1}})}else{mega.anim=_tpt.gsap.to(mega,{height:0,display:"none",duration:M.duration,ease:"sine.out",onComplete:()=>{mega.inAnimate=!1;mega.isShown=!1}})}},stickyScroll:()=>{var topBar=document.querySelector('.topbar');var menuBar=document.querySelector('.menubar');var mobileMenu=document.querySelector('.tp-megamenu-mobile-block');if(!topBar||!menuBar||!mobileMenu)return;var topBarHeight=topBar.offsetHeight;var spacer=document.getElementById('menu-bar-spacer')||document.createElement('div');spacer.id='menu-bar-spacer';var menuBarHeight=menuBar.offsetHeight;if(window.pageYOffset>topBarHeight){if(!document.getElementById('menu-bar-spacer')){spacer.style.width='100%';spacer.style.height=menuBarHeight+'px';menuBar.parentNode.insertBefore(spacer,menuBar)}
menuBar.classList.add('sticky');mobileMenu.classList.add('stickymobile')}else{menuBar.classList.remove('sticky');mobileMenu.classList.remove('stickymobile');if(document.getElementById('menu-bar-spacer')){spacer.parentNode.removeChild(spacer)}}},wait:()=>{let waitNav=setInterval(()=>{if(document.querySelectorAll('.wp-block-navigation').length&&_tpt.gsap!=undefined){clearInterval(waitNav);TpMegaMenu.init()}},100)}}
TpMegaMenu.wait()